#!/usr/bin/env bash
set -euo pipefail

# Auto-generated by multi-git skill. Do not edit manually.
# Re-run /multi-git to reconfigure.

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
CONFIG="$PROJECT_ROOT/.git/multi-git.yml"
WORK_DIR="/tmp/multi-git-publish-$$"

if [ ! -f "$CONFIG" ]; then
    echo "ERROR: $CONFIG not found. Run /multi-git to initialize."
    exit 1
fi

# Parse config
remote_name=$(grep '^remote_name:' "$CONFIG" | sed 's/remote_name: *//')
remote_url=$(grep '^remote_url:' "$CONFIG" | sed 's/remote_url: *//')
branch=$(grep '^branch:' "$CONFIG" | sed 's/branch: *//')
strip_co_authors=$(grep '^strip_co_authors:' "$CONFIG" | sed 's/strip_co_authors: *//')

# Collect exclude paths (only lines under "exclude:" block)
mapfile -t exclude_paths < <(sed -n '/^exclude:/,/^[^ ]/{/^ *- /p}' "$CONFIG" | sed 's/^ *- *//;s/ *#.*//')

cleanup() { rm -rf "$WORK_DIR"; }
trap cleanup EXIT

echo "==> Cloning repo to temporary directory..."
git clone --branch "$branch" --single-branch "file://$PROJECT_ROOT" "$WORK_DIR" 2>/dev/null
cd "$WORK_DIR"

echo "==> Filtering internal paths..."
FILTER_ARGS=()
for path in "${exclude_paths[@]}"; do
    FILTER_ARGS+=(--path "$path" --invert-paths)
done

if [ "$strip_co_authors" = "true" ]; then
    FILTER_ARGS+=(--message-callback 'import re; return re.sub(rb"\n\s*Co-Authored-By:.*", b"", message)')
fi

git filter-repo "${FILTER_ARGS[@]}" --force --quiet

echo "==> Pushing to $remote_name ($branch)..."
git remote add "$remote_name" "$remote_url"
git push "$remote_name" "$branch" --force

echo "==> Done. Published to $remote_name (excluded internal paths)."
